    "question": "(UTME 2024) Which class of rocks forms from the cooling and solidification of molten magma beneath the Earth's crust or lava on the surface?",
    "options": [
      "Igneous rocks",
      "Sedimentary rocks",
      "Metamorphic rocks",
      "Fossiliferous rocks"
    ],
